function hostedServer(directory) {
  const server = createServer(directory), normal = server.listeners("request")[0]; server.removeAllListeners("request");
  server.on("request", (req, res) => {
    const url = new URL(req.url, "http://127.0.0.1");
    if (url.pathname === "/__circuit-wrapper") { res.writeHead(200, { "content-type": "text/html" }); res.end('<!doctype html><meta name="viewport" content="width=device-width,initial-scale=1"><style>html,body{height:100%;margin:0;overflow:hidden}iframe{width:100%;height:100%;border:0;display:block}</style><iframe id="activity" src="/circuit-workbench/index.html" allow="fullscreen"></iframe>'); return; }
    if (url.pathname === "/__circuit-host") { const type = url.searchParams.get("case"), nested = type === "T2", element = type === "T3", blocked = url.searchParams.has("blocked"); res.writeHead(200, { "content-type": "text/html", ...(blocked ? {"Permissions-Policy":"fullscreen=()"} : {}) }); res.end(`<!doctype html><meta name="viewport" content="width=device-width,initial-scale=1"><style>html,body{margin:0;${element ? "height:100%;overflow:hidden" : ""}}#owner{${element ? "height:100dvh;overflow:auto" : ""}}.before{height:300px}.after{height:1400px}iframe{display:block;border:0;width:100%;height:500px}</style><div id="owner"><div class="before"></div><iframe id="${nested ? "wrapper" : "activity"}" src="${nested ? "/__circuit-wrapper" : "/circuit-workbench/index.html"}" allow="${blocked ? "fullscreen 'none'" : "fullscreen"}"></iframe><div class="after"></div></div>`); return; }
    normal(req, res);
  }); return server;
}
