      if (params.has('denyStorage')) {window.__storageProbeStacks=[];for (const key of ['localStorage','sessionStorage']) Object.defineProperty(window,key,{get(){window.__storageProbes++;window.__storageProbeStacks.push(new Error().stack);throw new DOMException('Storage denied','SecurityError');}});}
